#include "longhorn.h"
static GtkWidget*start_window;
void longhorn_hide_start_menu(void){if(start_window)gtk_window_hide(GTK_WINDOW(start_window));}
void longhorn_show_start_menu(GtkApplication*a){if(!start_window)create_start_menu(a);else gtk_window_present(GTK_WINDOW(start_window));}
void longhorn_toggle_start_menu(GtkApplication*a){if(!start_window){create_start_menu(a);return;}if(gtk_widget_get_visible(start_window))longhorn_hide_start_menu();else gtk_window_present(GTK_WINDOW(start_window));}
static void open_docs(GtkButton*b,gpointer d){(void)b;create_file_explorer(GTK_APPLICATION(d),g_get_home_dir());longhorn_hide_start_menu();}
static void close_menu(GtkButton*b,gpointer d){(void)b;(void)d;longhorn_hide_start_menu();}
void create_start_menu(GtkApplication*app){GtkWidget*w=gtk_application_window_new(app);start_window=w;GtkWindow*win=GTK_WINDOW(w);gtk_layer_init_for_window(win);gtk_layer_set_layer(win,GTK_LAYER_SHELL_LAYER_OVERLAY);gtk_layer_set_anchor(win,GTK_LAYER_SHELL_EDGE_BOTTOM,TRUE);gtk_layer_set_anchor(win,GTK_LAYER_SHELL_EDGE_LEFT,TRUE);gtk_layer_set_margin(win,GTK_LAYER_SHELL_EDGE_BOTTOM,LH4051_PANEL_HEIGHT);gtk_widget_set_size_request(w,620,430);gtk_layer_set_keyboard_mode(win,GTK_LAYER_SHELL_KEYBOARD_MODE_ON_DEMAND);GtkWidget*r=gtk_box_new(GTK_ORIENTATION_HORIZONTAL,0);gtk_widget_add_css_class(r,"lh-start-menu");gtk_window_set_child(win,r);GtkWidget*l=gtk_box_new(GTK_ORIENTATION_VERTICAL,3);gtk_widget_set_size_request(l,275,-1);gtk_widget_add_css_class(l,"lh-start-left");GtkWidget*h=gtk_label_new("◉  Administrator");gtk_widget_add_css_class(h,"lh-start-header");gtk_label_set_xalign(GTK_LABEL(h),0);gtk_box_append(GTK_BOX(l),h);const char*apps[]={"🌐  Internet Explorer","▶  Windows Media Player","📁  My Documents","📝  Notepad","🧮  Calculator","⚙  Control Panel"};for(guint x=0;x<G_N_ELEMENTS(apps);x++){GtkWidget*b=gtk_button_new_with_label(apps[x]);gtk_widget_add_css_class(b,"lh-start-item");gtk_box_append(GTK_BOX(l),b);if(x==2)g_signal_connect(b,"clicked",G_CALLBACK(open_docs),app);}GtkWidget*sp=gtk_box_new(GTK_ORIENTATION_VERTICAL,0);gtk_widget_set_vexpand(sp,TRUE);gtk_box_append(GTK_BOX(l),sp);gtk_box_append(GTK_BOX(l),gtk_button_new_with_label("All Programs  ›"));gtk_box_append(GTK_BOX(r),l);GtkWidget*rr=gtk_box_new(GTK_ORIENTATION_VERTICAL,4);gtk_widget_add_css_class(rr,"lh-start-right");gtk_box_append(GTK_BOX(rr),gtk_label_new("Places and system"));const char*links[]={"📄  Documents","🖼  Pictures","🎬  Videos","🖨  Printers and Faxes","⚙  Control Panel","🔎  Search"};for(guint x=0;x<G_N_ELEMENTS(links);x++)gtk_box_append(GTK_BOX(rr),gtk_button_new_with_label(links[x]));GtkWidget*sp2=gtk_box_new(GTK_ORIENTATION_VERTICAL,0);gtk_widget_set_vexpand(sp2,TRUE);gtk_box_append(GTK_BOX(rr),sp2);GtkWidget*s=gtk_box_new(GTK_ORIENTATION_HORIZONTAL,5);gtk_box_append(GTK_BOX(s),gtk_button_new_with_label("🔑  Log Off"));gtk_box_append(GTK_BOX(s),gtk_button_new_with_label("⏻  Turn Off Computer"));gtk_box_append(GTK_BOX(rr),s);GtkWidget*c=gtk_button_new_with_label("Close Start Menu");g_signal_connect(c,"clicked",G_CALLBACK(close_menu),NULL);gtk_box_append(GTK_BOX(rr),c);gtk_box_append(GTK_BOX(r),rr);gtk_window_present(win);}
